<!DOCTYPE html>
<html lang="pt-BR">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
    <title>Yoru Shield VPN</title>
    <!-- Firebase sob demanda -->
    <script>
      window.__loadFirebase = function(cb) {
        if (window.firebase) { if (cb) cb(); return; }
        if (window.__fbLoading) { window.__fbLoading.push(cb); return; }
        window.__fbLoading = cb ? [cb] : [];
        var a = document.createElement('script');
        a.src = 'https://www.gstatic.com/firebasejs/10.12.0/firebase-app-compat.js';
        a.onload = function() {
          var b = document.createElement('script');
          b.src = 'https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore-compat.js';
          b.onload = function() {
            var q = window.__fbLoading || []; window.__fbLoading = null;
            q.forEach(function(fn){ try{ fn&&fn(); }catch(e){} });
          };
          document.head.appendChild(b);
        };
        document.head.appendChild(a);
      };
    </script>

    <!-- Sistema de Cache de Imagens (logo + bandeiras) -->
    <script>
    window.ImageCache = {
        PREFIX: 'yoru_img_',
        DURATION: 7 * 24 * 60 * 60 * 1000, // 7 dias

        get: function(url) {
            if (!url || (!url.startsWith('http') && !url.startsWith('https'))) return null;
            try {
                var key = this.PREFIX + btoa(url).replace(/[/+=]/g, '_');
                var raw = localStorage.getItem(key);
                if (!raw) return null;
                var entry = JSON.parse(raw);
                if (!entry || !entry.data) return null;
                if (Date.now() - entry.ts > this.DURATION) {
                    localStorage.removeItem(key);
                    return null;
                }
                return entry.data;
            } catch(e) { return null; }
        },

        set: function(url, dataUrl) {
            if (!url || !dataUrl) return;
            try {
                var key = this.PREFIX + btoa(url).replace(/[/+=]/g, '_');
                localStorage.setItem(key, JSON.stringify({
                    ts: Date.now(),
                    data: dataUrl
                }));
                this.cleanup();
            } catch(e) {
                if (e.name === 'QuotaExceededError') {
                    this.cleanup(true);
                    try { 
                        localStorage.setItem(key, JSON.stringify({
                            ts: Date.now(),
                            data: dataUrl
                        })); 
                    } catch(e2) {}
                }
            }
        },

        cleanup: function(aggressive) {
            try {
                var items = [];
                for (var i = 0; i < localStorage.length; i++) {
                    var key = localStorage.key(i);
                    if (key && key.startsWith(this.PREFIX)) {
                        try {
                            var entry = JSON.parse(localStorage.getItem(key));
                            items.push({ key: key, ts: entry.ts || 0 });
                        } catch(e) {}
                    }
                }
                if (items.length < 20 && !aggressive) return;
                items.sort(function(a, b) { return a.ts - b.ts; });
                var removeCount = aggressive ? Math.ceil(items.length / 2) : Math.ceil(items.length * 0.3);
                for (var j = 0; j < removeCount && j < items.length; j++) {
                    localStorage.removeItem(items[j].key);
                }
            } catch(e) {}
        },

        load: function(url) {
            var self = this;
            return new Promise(function(resolve) {
                if (!url || (!url.startsWith('http') && !url.startsWith('https'))) {
                    resolve(null);
                    return;
                }
                var cached = self.get(url);
                if (cached) {
                    resolve(cached);
                    return;
                }
                var controller = new AbortController();
                var timeout = setTimeout(function() { controller.abort(); }, 8000);
                fetch(url, { 
                    signal: controller.signal,
                    mode: 'cors',
                    cache: 'default'
                })
                .then(function(response) {
                    clearTimeout(timeout);
                    if (!response.ok) throw new Error('HTTP ' + response.status);
                    return response.blob();
                })
                .then(function(blob) {
                    var reader = new FileReader();
                    reader.onload = function() {
                        var dataUrl = reader.result;
                        if (dataUrl && dataUrl.startsWith('data:image')) {
                            self.set(url, dataUrl);
                            resolve(dataUrl);
                        } else {
                            resolve(null);
                        }
                    };
                    reader.onerror = function() { resolve(null); };
                    reader.readAsDataURL(blob);
                })
                .catch(function(err) {
                    clearTimeout(timeout);
                    console.warn('Image cache fetch error:', err.message);
                    resolve(null);
                });
            });
        },

        loadIntoElement: function(url, element, fallbackEmoji) {
            if (typeof element === 'string') {
                element = document.getElementById(element);
            }
            if (!element) return;
            if (!url) {
                if (fallbackEmoji) element.innerHTML = fallbackEmoji;
                return;
            }
            if (url.startsWith('file://') || url.startsWith('data:')) {
                element.innerHTML = '<img src="' + url + '" style="width:100%;height:100%;object-fit:cover;" alt="">';
                return;
            }
            if (fallbackEmoji) {
                element.innerHTML = fallbackEmoji;
            }
            var self = this;
            this.load(url).then(function(dataUrl) {
                if (dataUrl && element) {
                    element.innerHTML = '<img src="' + dataUrl + '" style="width:100%;height:100%;object-fit:cover;" alt="">';
                }
            });
        }
    };

    // Limpeza periódica do cache (a cada 24h)
    (function() {
        var CLEAN_KEY = 'yoru_img_clean_ts';
        var now = Date.now();
        var last = parseInt(localStorage.getItem(CLEAN_KEY) || '0', 10);
        if (now - last > 86400000) {
            window.ImageCache.cleanup(false);
            localStorage.setItem(CLEAN_KEY, String(now));
        }
    })();
    </script>

