                <div class="layout-chip" data-radical-id="float" onclick="setRadical('float')"><div class="layout-preview" style="display:flex;align-items:center;justify-content:center;"><div style="width:30px;height:30px;background:var(--accent-a);border-radius:50%;"></div></div><span class="layout-chip-label">Minimal Float</span></div>
                <div class="layout-chip" data-radical-id="terminal" onclick="setRadical('terminal')"><div class="layout-preview" style="background:#0a0a0a;color:#0f0;font-family:monospace;font-size:9px;text-align:left;padding:6px;">root@yoru:~$<br>_</div><span class="layout-chip-label">Terminal</span></div>
                <div class="layout-chip" data-radical-id="carousel" onclick="setRadical('carousel')"><div class="layout-preview" style="display:flex;align-items:flex-end;justify-content:center;padding-bottom:6px;gap:4px;"><span style="width:8px;height:8px;background:var(--accent-a);border-radius:50%;"></span><span style="width:6px;height:6px;background:var(--text-muted);border-radius:50%;"></span><span style="width:6px;height:6px;background:var(--text-muted);border-radius:50%;"></span></div><span class="layout-chip-label">Carrossel</span></div>
            </div>
        </div>
    </div>
</div>

<div class="toast-box"><div class="toast" id="toast"></div></div>

<script>
(function () {
'use strict';

// Atalho para o cache
var IC = window.ImageCache;

var THEME_KEY = 'yoru_theme', LAYOUT_KEY = 'yoru_layout', RADICAL_KEY = 'yoru_radical';
var isXrayMode = false;

window.setTheme = function (id) {
  document.documentElement.setAttribute('data-theme', id === 'dark' ? '' : id);
  document.querySelectorAll('.theme-chip').forEach(function (c) { c.classList.toggle('active', c.getAttribute('data-theme-id') === id); });
  try { localStorage.setItem(THEME_KEY, id); } catch(e) {}
  try { if (window.Android && typeof Android.saveTheme === 'function') Android.saveTheme(id); } catch(e) {}
};
function loadTheme() {
  var saved = null;
  try { if (window.Android && typeof Android.getSavedTheme === 'function') saved = Android.getSavedTheme(); } catch(e) {}
  if (!saved) { try { saved = localStorage.getItem(THEME_KEY); } catch(e) {} }
  if (saved && saved !== 'dark') setTheme(saved);
}

window.setLayout = function (id) {
  document.documentElement.setAttribute('data-layout', id === 'default' ? '' : id);
  document.querySelectorAll('#layout-grid .layout-chip').forEach(function (c) { c.classList.toggle('active', c.getAttribute('data-layout-id') === id); });
  try { localStorage.setItem(LAYOUT_KEY, id); } catch(e) {}
  try { if (window.Android && typeof Android.saveLayout === 'function') Android.saveLayout(id); } catch(e) {}
  toast('Estilo visual aplicado!', 'ok');
};
function loadLayout() {
  var saved = null;
  try { if (window.Android && typeof Android.getSavedLayout === 'function') saved = Android.getSavedLayout(); } catch(e) {}
  if (!saved) { try { saved = localStorage.getItem(LAYOUT_KEY); } catch(e) {} }
  if (saved && saved !== 'default') setLayout(saved);
}

var currentRadical = 'none';

function removeRadial() { var menu = document.getElementById('radial-menu'); if (menu) menu.innerHTML = ''; document.removeEventListener('scroll', updateRadialPos); window.removeEventListener('resize', updateRadialPos); }
function applyRadial() {
  removeRadial();
  var menu = document.getElementById('radial-menu');
  var target = document.querySelector('.btn-connect-main');
  if (!target || !menu) return;
  var rect = target.getBoundingClientRect();
  var cx = rect.left + rect.width/2, cy = rect.top + rect.height/2, r = 130;
  var items = [
    { label: 'Home', icon: '🏠', page: 'home' },
    { label: 'Tema', icon: '🎨', page: 'theme' },
    { label: 'Ajustes', icon: '⚙️', page: 'ajustes' },
    { label: 'Grupo', icon: '💬', action: function(){ openGroupChat(); } }
  ];
  items.forEach(function(item, i) {
    var angle = (i / items.length) * Math.PI * 2 - Math.PI/2;
    var btn = document.createElement('button');
    btn.className = 'radial-btn';
    btn.innerHTML = item.icon;
    btn.title = item.label;
    btn.style.left = (cx + Math.cos(angle) * r - 28) + 'px';
    btn.style.top = (cy + Math.sin(angle) * r - 28) + 'px';
    btn.onclick = function() { if (item.page) showPage(item.page); if (item.action) item.action(); };
    menu.appendChild(btn);
  });
  updateRadialPos = function() {
    var rect2 = target.getBoundingClientRect();
    var cx2 = rect2.left + rect2.width/2, cy2 = rect2.top + rect2.height/2;
    menu.querySelectorAll('.radial-btn').forEach(function(b, i2) {
      var a = (i2 / items.length) * Math.PI * 2 - Math.PI/2;
      b.style.left = (cx2 + Math.cos(a) * r - 28) + 'px';
      b.style.top = (cy2 + Math.sin(a) * r - 28) + 'px';
    });
  };
  document.addEventListener('scroll', updateRadialPos, {passive:true});
  window.addEventListener('resize', updateRadialPos);
}
var updateRadialPos = function(){};

function removeSidebar() { document.getElementById('sidebar-nav').style.display = 'none'; }
function applySidebar() { document.getElementById('sidebar-nav').style.display = 'flex'; }
window.sidebarNav = function(page) { showPage(page); document.querySelectorAll('#sidebar-nav .sidebar-btn').forEach(function(b){ b.classList.toggle('active', b.getAttribute('data-page')===page); }); };

function removeDashboard() { document.getElementById('dashboard-overlay').style.display = 'none'; document.getElementById('page-home').style.display = ''; }
function applyDashboard() { document.getElementById('dashboard-overlay').style.display = 'flex'; document.getElementById('page-home').style.display = 'none'; updateDashboardValues(); }
function updateDashboardValues() {
  setText('dash-status-val', app.connected ? 'Conectado' : 'Desconectado');
  var badge = document.getElementById('dash-status-badge');
  if (badge) { badge.textContent = app.connected ? 'ON' : 'OFF'; badge.style.background = app.connected ? 'rgba(16,185,129,0.15)' : 'rgba(239,68,68,0.15)'; badge.style.color = app.connected ? '#10b981' : '#ef4444'; }
  setText('dash-server-val', (document.getElementById('server-title')||{}).textContent||'Auto');
  setText('dash-dl-val', (document.getElementById('speed-dl')||{}).textContent||'0 B/s');
  setText('dash-ul-val', (document.getElementById('speed-ul')||{}).textContent||'0 B/s');
}
setInterval(function(){ if(currentRadical==='dashboard') updateDashboardValues(); }, 5000);
window.dashboardAction = function(action) {
  if (action === 'connect') { document.getElementById('btn-connect').click(); }
  else if (action === 'servers') { if (app.connected) { toast('Desconecte antes de trocar de rede.', 'err'); return; } buildServerList('normal'); openModal('modal-servers'); }
  else if (action === 'creds') { if (app.connected) { toast('Desconecte para alterar credenciais.', 'err'); return; } toggleCredsMode(); }
  else if (action === 'logs') { openLogsModal(); }
};

function removeFloat() { document.querySelector('.float-actions').style.display = 'none'; }
function applyFloat() { document.querySelector('.float-actions').style.display = 'flex'; }

function removeTerminal() { document.getElementById('terminal-container').style.display = 'none'; document.querySelector('.app-shell').style.display = ''; document.querySelector('.bottom-nav').style.display = ''; }
function applyTerminal() { document.getElementById('terminal-container').style.display = 'flex'; document.querySelector('.app-shell').style.display = 'none'; document.querySelector('.bottom-nav').style.display = 'none'; var inp = document.getElementById('terminal-input'); if (inp) { inp.focus(); inp.value = ''; } }
function terminalExec(cmd) {
  var out = document.getElementById('terminal-output'); if (!out) return;
  cmd = cmd.trim().toLowerCase(); var response = '';
  if (cmd === 'help') { response = 'Commands:\n  connect    - Start VPN\n  disconnect - Stop VPN\n  status     - Show status\n  servers    - List servers\n  logs       - View logs\n  clear      - Clear screen\n  exit       - Exit terminal\n  help       - This help'; }
  else if (cmd === 'connect') { A.connect(); applyState('INICIANDO'); response = 'Connecting...'; }
  else if (cmd === 'disconnect') { if (app.connected) { A.connect(); applyState('PARANDO'); response = 'Disconnecting...'; } else response = 'Not connected.'; }
  else if (cmd === 'status') { response = 'Status: ' + app.rawState + '\nConnected: ' + (app.connected ? 'Yes' : 'No'); }
  else if (cmd === 'servers') { var servers = A.getServers(); response = servers.length ? servers.map(function(s,i){ return '  ['+i+'] '+s.Name; }).join('\n') : 'No servers loaded.'; }
  else if (cmd === 'logs') { var logs = A.getLogs(); response = logs.length ? logs.slice(-5).map(function(l){ return '  ['+l.level+'] '+l.message; }).join('\n') : 'No logs.'; }
  else if (cmd === 'clear') { out.innerHTML = ''; return; }
  else if (cmd === 'exit') { setRadical('none'); return; }
  else if (cmd) { response = 'Unknown command: ' + cmd + '\nType "help" for commands.'; }
  if (response) out.innerHTML += '\n<span style="color:#0f0;">root@yoru:~$</span> ' + cmd + '\n' + response + '\n';
  out.scrollTop = out.scrollHeight;
}

var carouselIndex = 0;
function removeCarousel() { document.getElementById('carousel-container').style.display = 'none'; document.querySelector('.app-shell').style.display = ''; document.querySelector('.bottom-nav').style.display = ''; }
function applyCarousel() { document.getElementById('carousel-container').style.display = 'flex'; document.querySelector('.app-shell').style.display = 'none'; document.querySelector('.bottom-nav').style.display = 'none'; buildCarouselSlides(); goCarousel(0); }
function buildCarouselSlides() {
  var homeSlide = document.getElementById('carousel-slide-home');
  if (homeSlide && homeSlide.children.length === 0) {
    var stripIds = function(el) {
      if (el.id) el.id = 'cloned-' + el.id;
      el.querySelectorAll('[id]').forEach(function(c) { c.id = 'cloned-' + c.id; });
      return el;
    };
    var heroClone = stripIds(document.querySelector('.hero-area').cloneNode(true));
    var heroBtn = heroClone.querySelector('.btn-connect-main');
    if (heroBtn) heroBtn.onclick = function(){ document.getElementById('btn-connect').click(); };
    homeSlide.appendChild(heroClone);
    var sc = document.getElementById('select-server');
    if (sc) homeSlide.appendChild(stripIds(sc.cloneNode(true)));
    var stats = document.getElementById('stats-row');
    if (stats) homeSlide.appendChild(stripIds(stats.cloneNode(true)));
    var credsClone = stripIds(document.querySelector('.creds-card').cloneNode(true));
    var logsBtn = credsClone.querySelector('.btn-logs-quick');
    if (logsBtn) logsBtn.onclick = function(){ openLogsModal(); };
    homeSlide.appendChild(credsClone);
  }
  var themeSlide = document.getElementById('carousel-slide-theme');
  if (themeSlide) {
    themeSlide.innerHTML = '<h2 style="font-weight:800;margin-bottom:12px;">Tema</h2>';
    var themeContent = document.querySelector('#page-theme .theme-section').cloneNode(true);
    themeSlide.appendChild(themeContent);
    var btnUpdate = document.getElementById('btn-update-config').cloneNode(true);
    btnUpdate.onclick = function(){ A.checkUpdate(); };
    themeSlide.appendChild(btnUpdate);
  }
  var ajustesSlide = document.getElementById('carousel-slide-ajustes');
  if (ajustesSlide) {
    ajustesSlide.innerHTML = '<h2 style="font-weight:800;margin-bottom:12px;">Ajustes</h2>';
    var timeCardClone = document.getElementById('time-card').cloneNode(true);
    ajustesSlide.appendChild(timeCardClone);
    var checkuserClone = document.getElementById('checkuser-card').cloneNode(true);
    ajustesSlide.appendChild(checkuserClone);
    var settingsClone = document.getElementById('settings-card').cloneNode(true);
    ajustesSlide.appendChild(settingsClone);
  }
}
function goCarousel(idx) { carouselIndex = idx; document.getElementById('carousel-track').style.transform = 'translateX(-'+(idx*100)+'%)'; document.querySelectorAll('#carousel-dots .carousel-dot').forEach(function(d,i){ d.classList.toggle('active', i===idx); }); }

window.setRadical = function(id) {
  if (id === currentRadical) return;
  if (currentRadical === 'radial') removeRadial();
  else if (currentRadical === 'sidebar') removeSidebar();
  else if (currentRadical === 'dashboard') removeDashboard();
  else if (currentRadical === 'float') removeFloat();
  else if (currentRadical === 'terminal') removeTerminal();
  else if (currentRadical === 'carousel') removeCarousel();
  document.documentElement.removeAttribute('data-radical');
  if (id === 'none' || !id) { document.querySelector('.app-shell').style.display = ''; document.querySelector('.bottom-nav').style.display = ''; currentRadical = 'none'; }
  else { document.documentElement.setAttribute('data-radical', id); if (id === 'radial') applyRadial(); else if (id === 'sidebar') applySidebar(); else if (id === 'dashboard') applyDashboard(); else if (id === 'float') applyFloat(); else if (id === 'terminal') applyTerminal(); else if (id === 'carousel') applyCarousel(); currentRadical = id; }
  document.querySelectorAll('#radical-grid .layout-chip').forEach(function(c){ c.classList.toggle('active', c.getAttribute('data-radical-id')===id); });
  try { localStorage.setItem(RADICAL_KEY, id); } catch(e) {}
  try { if (window.Android && typeof Android.saveRadicalLayout === 'function') Android.saveRadicalLayout(id); } catch(e) {}
  if (id !== 'none') toast('Layout estrutural aplicado!', 'ok'); else toast('Layout original restaurado.', '');
};
function loadRadical() {
  var saved = null;
  try { if (window.Android && typeof Android.getSavedRadicalLayout === 'function') saved = Android.getSavedRadicalLayout(); } catch(e) {}
  if (!saved) { try { saved = localStorage.getItem(RADICAL_KEY); } catch(e) {} }
  if (saved && saved !== 'none') setRadical(saved);
}

var A = {
  call: function (m, arg) { try { if (window.Android && typeof window.Android[m] === 'function') return arg !== undefined ? window.Android[m](arg) : window.Android[m](); } catch (e) {} return null; },
  parse: function (raw, fb) { try { return JSON.parse(raw) || fb; } catch(e) { return fb; } },
  connect: function(){ A.call('connect'); },
  getStatus: function(){ return A.call('getStatus') || 'DESCONECTADO'; },
  getServers: function(){ return A.parse(A.call('getServers'),[]); },
  getSelected: function(){ return A.parse(A.call('getSelectedServer'),{}); },
  selectServer: function(pos){ A.call('selectServer',pos); },
  getMultiServers: function(){ return A.parse(A.call('getMultiServers'),[]); },
  getSelectedMulti: function(){ return A.parse(A.call('getSelectedMultiServer'),{}); },
  getServerMode: function(){
    var v = A.call('getServerMode');
    if (v === null || v === undefined || v === '') v = A.call('getServerModeSelection');
    return Number(v || 0);
  },
  selectMultiServer: function(pos){ A.call('selectMultiServer',pos); },
  hasOfflineMode: function(){
    try {
      if (window.Android && typeof Android.hasOfflineMode === 'function') return !!Android.hasOfflineMode();
      return false;
    } catch(e){ return false; }
  },
  getOfflineServers: function(){
    try {
      if (window.Android && typeof Android.getOfflineServers === 'function')
        return A.parse(Android.getOfflineServers(), []);
      return [];
    } catch(e){ return []; }
  },
  selectOfflineServer: function(id){
    try { if (window.Android && typeof Android.selectOfflineServer === 'function') Android.selectOfflineServer(id || ''); } catch(e){}
  },
  editOfflineServer: function(id){
    try { if (window.Android && typeof Android.editOfflineServer === 'function') Android.editOfflineServer(id || ''); } catch(e){}
  },
  deleteOfflineServer: function(id){
    try { if (window.Android && typeof Android.deleteOfflineServer === 'function') Android.deleteOfflineServer(id || ''); } catch(e){}
  },
  reloadConfig: function(){
    try { if (window.Android && typeof Android.reloadConfig === 'function') Android.reloadConfig(); } catch(e){}
  },
  getNote: function(){ return A.call('getNote') || ''; },
  getVersion: function(){ return A.call('getVersion') || ''; },
  getLogs: function(){ return A.parse(A.call('getLogs'),[]); },
  clearLogs: function(){ A.call('clearLogs'); },
  checkUpdate: function(){ A.call('checkUpdate'); },
  requestInterstitial: function(){ A.call('requestInterstitial'); },
  isAdsEnabled: function(){ return window.Android && typeof Android.isAdsEnabled==='function' ? Android.isAdsEnabled() : false; },
  getTimeLeft: function(){ return window.Android && typeof Android.getTimeLeft==='function' ? Android.getTimeLeft() : 0; },
  watchAd: function(){ A.call('watchAd'); },
  getSettings: function(){ return A.parse(A.call('getSettings'), {}); },
  saveSettings: function(obj){ try { if(window.Android && typeof Android.saveSettings==='function') Android.saveSettings(JSON.stringify(obj)); } catch(e){} },
  getNetSpeed: function(){ try { return window.Android && typeof Android.getNetSpeed==='function' ? Android.getNetSpeed() : '{}'; } catch(e){ return '{}'; } },
  measurePing: function(){ try { return window.Android && typeof Android.measurePing==='function' ? Android.measurePing() : -1; } catch(e){ return -1; } },
  getFullConfig: function(){ return A.parse(A.call('getFullConfig'), {}); },
  openLogs: function(){ A.call('openLogs'); }
};

var STATE = {
  CONECTADO:{cls:'st-conectado',label:'STATUS: CONECTADO',sub:'Sua conexão está 100% segura e privada.',btn:'Desconectar',hint:'⚡ TOQUE PARA DESCONECTAR ⚡'},
  DESCONECTADO:{cls:'',label:'STATUS: DESCONECTADO',sub:'Toque no botão para iniciar a VPN.',btn:'Conectar',hint:'⚡ TOQUE PARA CONECTAR ⚡'},
  INICIANDO:{cls:'st-conectando',label:'STATUS: INICIANDO...',sub:'Preparando motor de conexão...',btn:'Aguarde...',hint:'⏳ AGUARDE...'},
  PARANDO:{cls:'st-conectando',label:'STATUS: PARANDO...',sub:'Encerrando túnel seguro...',btn:'Aguarde...',hint:'⏳ ENCERRANDO...'},
  CONECTANDO:{cls:'st-conectando',label:'STATUS: CONECTANDO...',sub:'Estabelecendo rota segura...',btn:'Aguarde...',hint:'⏳ CONECTANDO...'},
  AGUARDANDO:{cls:'st-conectando',label:'STATUS: AGUARDANDO...',sub:'Negociando com o servidor...',btn:'Aguarde...',hint:'⏳ AGUARDE...'},
  AUTENTICANDO:{cls:'st-conectando',label:'STATUS: AUTENTICANDO...',sub:'Validando suas credenciais...',btn:'Aguarde...',hint:'⏳ AUTENTICANDO...'},
  RECONECTANDO:{cls:'st-conectando',label:'STATUS: RECONECTANDO...',sub:'Restaurando sinal perdido...',btn:'Aguarde...',hint:'⏳ RECONECTANDO...'},
  NOPROCESS:{cls:'',label:'STATUS: DESCONECTADO',sub:'Toque no botão para iniciar a VPN.',btn:'Conectar',hint:'⚡ TOQUE PARA CONECTAR ⚡'},
  ERRO:{cls:'st-erro',label:'STATUS: ERRO',sub:'Verifique sua internet ou credenciais.',btn:'Tentar Novamente',hint:'⚠ TOQUE PARA TENTAR'}
};

var ALL_STATE_CLASSES = ['st-conectado','st-conectando','st-desconectado','st-erro'];
var app = { rawState:'NOPROCESS', connected:false, busy:false, startedAt:0, timerHandle:null, pollHandle:null };

function $(id) { return document.getElementById(id); }
function setText(id,v) { var el=$(id); if(el) el.textContent=String(v==null?'':v); }
function pad(n) { return String(n).padStart(2,'0'); }
function esc(s) { return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;'); }

function toast(msg, kind) {
  var el=$('toast'); if(!el) return;
  el.innerHTML=(kind==='ok'?'✅ ':kind==='err'?'❌ ':'⚠️ ')+msg;
  el.className='toast show '+(kind?kind:'');
  clearTimeout(el._t); el._t=setTimeout(function(){ el.className='toast'; },3000);
}

window.showPage = function(name) {
  document.querySelectorAll('.page').forEach(function(p){ p.classList.remove('active'); });
  document.querySelectorAll('.nav-btn').forEach(function(b){ b.classList.remove('active'); });
  var pg=$('page-'+name); if(pg) pg.classList.add('active');
  var nb=$('nav-'+name); if(nb) nb.classList.add('active');
  if(name==='servers') buildServerListPage();
  if (currentRadical === 'sidebar') sidebarNav(name);
  autoSaveCredentials();
};

function updateBlockedState() {
  var connected = app.connected;
  if (!connected) {
    ['creds-card','select-server','select-premium','select-offline','settings-card'].forEach(function(id){
      var el = $(id); if (!el) return;
      el.querySelectorAll('input, select, .creds-toggle').forEach(function(inp){
        inp.disabled = false;
      });
    });
  }
  ['creds-card','select-server','select-premium','select-offline','settings-card'].forEach(function(id){
    var el = $(id); if (!el) return;
    if (connected) {
      el.classList.add('blocked');
      el.querySelectorAll('input, select, .creds-toggle').forEach(function(inp){
        inp.disabled = true;
      });
    } else {
      el.classList.remove('blocked');
    }
  });
  var btnConnect = $('btn-connect'), btnLogs = $('btn-logs-quick');
  if (btnConnect) btnConnect.disabled = app.busy;
  if (btnLogs) btnLogs.disabled = false;
}

function applyState(raw, detail) {
  raw=String(raw||'NOPROCESS').toUpperCase().trim();
  app.rawState=raw;
  var s=STATE[raw]||STATE['NOPROCESS'];
  ALL_STATE_CLASSES.forEach(function(c){ document.body.classList.remove(c); });
  if(s.cls) document.body.classList.add(s.cls);
  setText('status-label',s.label);
  setText('status-detail',detail||s.sub);
  setText('btn-connect-text',s.btn||'Conectar');
  var hint = $('tap-hint');
  if (hint) hint.innerHTML = s.hint || '⚡ TOQUE PARA CONECTAR ⚡';
  app.connected=(raw==='CONECTADO');
  app.busy=['INICIANDO','CONECTANDO','AUTENTICANDO','AGUARDANDO','RECONECTANDO','PARANDO'].indexOf(raw)>=0;
  var btn = $('btn-connect'); if (btn) btn.disabled = app.busy;
  if(app.connected && !app.startedAt){ app.startedAt=Date.now(); startTimer(); }
  if(!app.connected && !app.busy){
    if(app.startedAt){ app.startedAt=0; stopTimer(); setText('timer-val','00:00'); setText('stat-time','00:00:00'); }
    var tb=$('timer-bar'); if(tb) tb.classList.remove('show');
  }
  var prot = $('stat-protection');
  if (prot) {
    if (app.connected) { prot.textContent = 'ATIVA'; prot.className = 'stat-value active'; }
    else if (app.busy) { prot.textContent = '…'; prot.className = 'stat-value'; }
    else { prot.textContent = 'INATIVA'; prot.className = 'stat-value inactive'; }
  }
  if (currentRadical === 'dashboard') updateDashboardValues();
  updateBlockedState();
  updateProfileCard();
  if (app.connected && !app.busy) startSpeedMeter();
  else if (!app.connected) stopSpeedMeter();
}

function startTimer() {
  stopTimer();
  var tb=$('timer-bar'); if(tb) tb.classList.add('show');
  app.timerHandle=setInterval(function(){
    var sec=Math.floor((Date.now()-app.startedAt)/1000);
    var h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),s=sec%60;
    var fmt = (h?pad(h)+':':'')+pad(m)+':'+pad(s);
    var full = pad(h)+':'+pad(m)+':'+pad(s);
    setText('timer-val', fmt);
    setText('stat-time', full);
  },1000);
}
function stopTimer(){ if(app.timerHandle){ clearInterval(app.timerHandle); app.timerHandle=null; } }
