var _hasEmbeddedCreds = false;

function findSelectedServerConfig() {
  try {
    var premium = A.getServerMode && A.getServerMode() === 1;
    var s = premium ? ((A.getSelectedMulti && A.getSelectedMulti()) || {})
                    : ((A.getSelected && A.getSelected()) || {});
    var full = A.getFullConfig ? A.getFullConfig() : {};
    var arr = premium ? ((full && full.MultiServs) || []) : ((full && full.Servers) || []);
    if (!arr.length) return null;
    var pos = Number(s.position);
    if (isFinite(pos) && pos >= 0 && pos < arr.length) return arr[pos] || null;
    for (var i = 0; i < arr.length; i++) {
      var it = arr[i] || {};
      if ((it.Name || '') === (s.Name || '') && (it.Info || '') === (s.Info || '')) return it;
    }
    for (var j = 0; j < arr.length; j++) {
      if ((arr[j].Name || '') === (s.Name || '')) return arr[j];
    }
  } catch(e) {}
  return null;
}

function credsStorageKey(mode) {
  try {
    var it = findSelectedServerConfig();
    var s = it || (A.getSelected && A.getSelected()) || {};
    var name = String(s.Name || '').trim();
    var info = String(s.Info || '').trim();
    if (!name && !info) return null;
    var m = mode || (isXrayMode ? 'xray' : 'ssh');
    return 'yoru_creds::' + name + '::' + info + '::' + m;
  } catch(e) { return null; }
}

function detectEmbeddedCredentials() {
  var user = '', pass = '', xray = '';
  try {
    var s = findSelectedServerConfig() || {};
    var ov = (s.openvpn && typeof s.openvpn === 'object') ? s.openvpn : {};
    user = String(s.USER || s.Username || s.username || s.user || s.login ||
                  ov.USER || ov.Username || ov.username || ov.user || ov.login || '').trim();
    pass = String(s.PASS || s.Password || s.password || s.pass ||
                  ov.PASS || ov.Password || ov.password || ov.pass || '').trim();
    xray = String(s.xray_uuid || s.xray_id || '').trim();
  } catch(e) {}
  _hasEmbeddedCreds = !!((user && pass) || xray);
  return _hasEmbeddedCreds;
}

function getServersMeta(listKey) {
  var meta = [];
  try {
    var full = A.getFullConfig ? A.getFullConfig() : A.parse(A.call('getFullConfig'), {});
    var arr = listKey === 'multi' ? (full.MultiServs || []) : (full.Servers || []);
    if (!arr || !arr.length) return meta;
    for (var i = 0; i < arr.length; i++) {
      var s = arr[i] || {};
      var ov = (s.openvpn && typeof s.openvpn === 'object') ? s.openvpn : {};
      var user = String(s.USER || s.Username || s.username || s.user || ov.USER || ov.Username || ov.username || ov.user || '').trim();
      var pass = String(s.PASS || s.Password || s.password || s.pass || ov.PASS || ov.Password || ov.password || ov.pass || '').trim();
      var xray = String(s.xray_uuid || s.xray_id || '').trim();
      var xaddr = String(s.xray_address || '').trim();
      var mode = String(s.MODE || s.Mode || s.TYPE || s.Tunnel || '').toUpperCase();
      var isXray = !!(xray || xaddr || mode.indexOf('XRAY') >= 0 || mode.indexOf('V2RAY') >= 0);
      var hasAuth = !!(user && pass) || !!xray;
      meta.push({ position: i, hasAuth: hasAuth, isXray: isXray });
    }
  } catch(e) {}
  return meta;
}

