function detectServerIsXray(s) {
  if (!s) return false;
  var xray = String(s.xray_uuid || s.xray_id || s.UUID || '').trim();
  var xaddr = String(s.xray_address || s.Address || '').trim();
  var mode = String(s.MODE || s.Mode || s.TYPE || s.Tunnel || '').toUpperCase();
  return !!(xray || xaddr || mode.indexOf('XRAY') >= 0 || mode.indexOf('V2RAY') >= 0 || mode.indexOf('VMESS') >= 0 || mode.indexOf('VLESS') >= 0);
}

function loadSavedCredentials(skipAuto){
  try {
    if (!skipAuto) {
      var s = findSelectedServerConfig() || (A.getSelected && A.getSelected()) || {};
      isXrayMode = detectServerIsXray(s);
      try { if (window.Android && typeof Android.saveCredsMode === 'function') Android.saveCredsMode(isXrayMode); } catch(e) {}
    }
    var A_ = window.Android;
    if (A_ && typeof A_.getSavedCredsMode === 'function' && skipAuto) {
      isXrayMode = !!A_.getSavedCredsMode();
    }
    if (_hasEmbeddedCreds) {
      if ($('ci-user')) $('ci-user').value = '';
      if ($('ci-pass')) $('ci-pass').value = '';
      if ($('ci-xray')) $('ci-xray').value = '';
    } else {
      var sshData = null, xrayData = null;
      try {
        var sshKey = credsStorageKey('ssh');
        if (sshKey) sshData = JSON.parse(localStorage.getItem(sshKey) || 'null');
      } catch(e1) {}
      try {
        var xrayKey = credsStorageKey('xray');
        if (xrayKey) xrayData = JSON.parse(localStorage.getItem(xrayKey) || 'null');
      } catch(e2) {}
      if ($('ci-user')) $('ci-user').value = (sshData && sshData.u) || '';
      if ($('ci-pass')) $('ci-pass').value = (sshData && sshData.p) || '';
      if ($('ci-xray')) $('ci-xray').value = (xrayData && xrayData.v2) || '';
    }
    applyCredsModeUI();
  } catch(e) { console.warn('loadSavedCredentials:', e); }
  updateCredentialsVisibility();
}

