var unreadBadge = document.getElementById('unread-badge');
var newMsgBar = document.getElementById('new-msg-bar');
var newMsgText = document.getElementById('new-msg-text');

function updateBadge(count) {
  if (!unreadBadge) return;
  if (count > 0) {
    unreadBadge.textContent = count > 99 ? '99+' : count;
    unreadBadge.classList.add('show');
  } else {
    unreadBadge.classList.remove('show');
  }
}

function showNewMsgBar(sender) {
  if (!newMsgBar || !newMsgText) return;
  newMsgText.textContent = sender ? 'Nova mensagem de ' + sender : 'Nova mensagem no grupo';
  newMsgBar.classList.add('show');
  clearTimeout(window._newMsgTimeout);
  window._newMsgTimeout = setTimeout(function() {
    newMsgBar.classList.remove('show');
  }, 5000);
}

window.hideNewMsgBar = function() {
  if (newMsgBar) newMsgBar.classList.remove('show');
  clearTimeout(window._newMsgTimeout);
};

window.openGroupChat = function() {
  unreadCount = 0;
  updateBadge(0);
  var maxTs = _firestoreMaxTs || 0;
  if (maxTs > 0) {
    lastSeenTimestamp = maxTs;
    localStorage.setItem('yoru_last_msg_ts', lastSeenTimestamp);
  } else {
    lastSeenTimestamp = Date.now();
    localStorage.setItem('yoru_last_msg_ts', lastSeenTimestamp);
  }
  hideNewMsgBar();
  if (window.Android && typeof Android.openChat === 'function') {
    Android.openChat();
  } else {
    toast('Chat aberto (modo web)', '');
  }
};

function startMessageListener() {
  if (msgListenerUnsubscribe) return;
  if (typeof firebase === 'undefined' || !firebase.firestore) {
    console.warn('Firebase não disponível');
    return;
  }
  try {
    firebase.initializeApp({
      apiKey: "AIzaSyC_iO6eI-h948a_rU8BOLb0H_pKio1PD9M",
      authDomain: "um-network.firebaseapp.com",
      projectId: "um-network",
      storageBucket: "um-network.firebasestorage.app",
      messagingSenderId: "520410782376",
      appId: "1:520410782376:android:153633be6fda8273f2809d"
    });
    const db = firebase.firestore();
    msgListenerUnsubscribe = db.collection("mensagens")
      .orderBy("timestamp", "asc")
      .onSnapshot(function(snapshot) {
        var maxTs = 0;
        var newMessagesCount = 0;
        snapshot.docChanges().forEach(function(change) {
          if (change.type !== 'added') return;
          var data = change.doc.data();
          if (!data || !data.timestamp) return;
          var ts = data.timestamp.toMillis ? data.timestamp.toMillis() : data.timestamp;
          if (ts > lastSeenTimestamp) newMessagesCount++;
          if (ts > maxTs) maxTs = ts;
        });
        _firestoreMaxTs = maxTs || lastSeenTimestamp;
        if (!initialLoadDone) {
          if (maxTs > 0) {
            lastSeenTimestamp = maxTs;
            localStorage.setItem('yoru_last_msg_ts', lastSeenTimestamp);
          }
          initialLoadDone = true;
          return;
        }
        if (newMessagesCount > 0) {
          var lastSender = null;
          snapshot.docChanges().forEach(function(change) {
            if (change.type !== 'added') return;
            var data = change.doc.data();
            if (data && data.timestamp) {
              var ts = data.timestamp.toMillis ? data.timestamp.toMillis() : data.timestamp;
              if (ts > lastSeenTimestamp) lastSender = data.nome || null;
            }
          });
          unreadCount += newMessagesCount;
          updateBadge(unreadCount);
          showNewMsgBar(lastSender);
          if (maxTs > lastSeenTimestamp) {
            lastSeenTimestamp = maxTs;
            localStorage.setItem('yoru_last_msg_ts', lastSeenTimestamp);
          }
        }
      }, function(error) {
        console.error('Erro no listener Firebase:', error);
      });
  } catch(e) {
    console.error('Falha ao iniciar Firebase:', e);
  }
}

function startFirebaseIntegration() {
  if (typeof window.__loadFirebase === 'function') {
    window.__loadFirebase(function() {
      startMessageListener();
      updateBadge(unreadCount);
    });
  } else {
    startMessageListener();
    updateBadge(unreadCount);
  }
}

function bind() {
  var btnConn = $('btn-connect');
  if (btnConn) btnConn.onclick = function() {
    var raw = app.rawState;
    if (raw === 'PARANDO') return;
    if (raw === 'CONECTADO') {
      A.connect();
      applyState('PARANDO', 'Encerrando túnel...');
      return;
    }
    if (!flushCredentialsBeforeConnect()) return;
    A.connect();
    if (['INICIANDO','CONECTANDO','AUTENTICANDO','AGUARDANDO','RECONECTANDO'].indexOf(raw) < 0) {
      applyState('INICIANDO', 'Preparando conexão...');
    }
  };
  var btnLogsQuick = $('btn-logs-quick');
  if (btnLogsQuick) btnLogsQuick.onclick = function(e) { if (e) { e.preventDefault(); e.stopPropagation(); } openLogsModal(); };
  var sServ = $('select-server');
  if (sServ) sServ.onclick = function() { if (app.connected) { toast('Desconecte antes de trocar de rede.', 'err'); return; } buildServerList('normal'); openModal('modal-servers'); };
  var pCard = $('select-premium');
  if (pCard) pCard.onclick = function() { if (app.connected) { toast('Desconecte antes de trocar de rede.', 'err'); return; } buildServerList('premium'); openModal('modal-servers'); };
  var oCard = $('select-offline');
  if (oCard) oCard.onclick = function(e) {
    if (e.target && (e.target.id === 'btn-offline-add' || (e.target.closest && e.target.closest('#btn-offline-add')))) {
      e.preventDefault(); e.stopPropagation();
      if (app.connected) { toast('Desconecte antes de editar.', 'err'); return; }
      A.editOfflineServer('');
      return;
    }
    if (app.connected) { toast('Desconecte antes de trocar de rede.', 'err'); return; }
    buildServerList('offline');
    openModal('modal-servers');
  };
  var btnOffAdd = $('btn-offline-add');
  if (btnOffAdd) btnOffAdd.onclick = function(e) {
    e.preventDefault(); e.stopPropagation();
    if (app.connected) { toast('Desconecte antes de editar.', 'err'); return; }
    A.editOfflineServer('');
  };
  var chipMulti = $('chip-multi');
  if (chipMulti) chipMulti.onclick = function(e) { e.stopPropagation(); toggleShowMulti(); };
  var chipSsh = $('chip-ssh');
  if (chipSsh) chipSsh.onclick = function(e) { e.stopPropagation(); setProtoFilter('ssh'); };
  var chipXray = $('chip-xray');
  if (chipXray) chipXray.onclick = function(e) { e.stopPropagation(); setProtoFilter('xray'); };
  var credsChipSsh = $('creds-chip-ssh');
  if (credsChipSsh) credsChipSsh.onclick = function() { setCredsMode(false); };
  var credsChipXray = $('creds-chip-xray');
  if (credsChipXray) credsChipXray.onclick = function() { setCredsMode(true); };
  ['ci-user','ci-pass','ci-xray'].forEach(function(id) {
    var el = $(id); if (!el) return;
    el.addEventListener('input', function() { autoSaveCredentials(false); });
    el.addEventListener('blur', function() { autoSaveCredentials(true); });
    el.addEventListener('change', function() { autoSaveCredentials(true); });
  });
  var btnUpdate = $('btn-update-config');
  if (btnUpdate) btnUpdate.onclick = function() { toast('Sincronizando...', ''); A.checkUpdate(); };
  var btnLayouts = $('btn-open-layouts');
  if (btnLayouts) btnLayouts.onclick = function() { openModal('modal-layouts'); };
  var dnsToggle = $('cfg-dns-forward');
  if (dnsToggle) { dnsToggle.onchange = function() { updateDepRows(); autoSaveSettings(); }; }
  var udpToggle = $('cfg-udp-forward');
  if (udpToggle) { udpToggle.onchange = function() { updateDepRows(); autoSaveSettings(); }; }
  var xrayToggle = $('cfg-xray-enabled');
  if (xrayToggle) { xrayToggle.onchange = function() { updateDepRows(); autoSaveSettings(); }; }
  var allSettingSwitches = document.querySelectorAll('#settings-card input[type="checkbox"]');
  allSettingSwitches.forEach(function(sw) { sw.addEventListener('change', autoSaveSettings); });
  var allSettingInputs = document.querySelectorAll('#settings-card input[type="text"], #settings-card input[type="number"], #settings-card select');
  allSettingInputs.forEach(function(inp) { inp.addEventListener('change', autoSaveSettings); inp.addEventListener('blur', autoSaveSettings); });
  var btnAd = $('btn-watch-ad');
  if (btnAd) btnAd.onclick = function() { btnAd.textContent = 'Aguarde...'; btnAd.disabled = true; A.watchAd(); };
  var termInput = document.getElementById('terminal-input');
  if (termInput) termInput.addEventListener('keydown', function(e) { if (e.key === 'Enter') { var cmd = termInput.value; terminalExec(cmd); termInput.value = ''; } });
  document.querySelectorAll('#carousel-dots .carousel-dot').forEach(function(dot) { dot.onclick = function() { goCarousel(parseInt(dot.getAttribute('data-index'))); }; });
  var touchStartX = 0;
  var track = document.getElementById('carousel-track');
  if (track) {
    track.addEventListener('touchstart', function(e) { touchStartX = e.touches[0].clientX; }, {passive: true});
    track.addEventListener('touchend', function(e) {
      var diff = touchStartX - e.changedTouches[0].clientX;
      if (Math.abs(diff) > 50) {
        if (diff > 0 && carouselIndex < 2) goCarousel(carouselIndex + 1);
        else if (diff < 0 && carouselIndex > 0) goCarousel(carouselIndex - 1);
      }
    });
  }
  document.querySelectorAll('.modal-close').forEach(function(b) { b.onclick = closeModal; });
  var mMask = $('modal-mask');
  if (mMask) mMask.onclick = function(e) { if (e.target === mMask) closeModal(); };
  setInterval(updateCelestial, 60000);
}

function createBubbles() {
  if (document.documentElement.getAttribute('data-beauty') !== 'on') return;
  for (var i = 0; i < 3; i++) {
    var bubble = document.createElement('div');
    bubble.className = 'floating-bubble';
    var size = Math.random() * 80 + 40;
    bubble.style.width = size + 'px';
    bubble.style.height = size + 'px';
    bubble.style.left = Math.random() * 100 + 'vw';
    bubble.style.top = Math.random() * 100 + 'vh';
    bubble.style.animationDuration = (Math.random() * 10 + 8) + 's';
    bubble.style.animationDelay = Math.random() * 5 + 's';
    document.body.appendChild(bubble);
  }
  for (var j = 0; j < 10; j++) {
    var star = document.createElement('div');
    var sSize = Math.random() * 3 + 1;
    star.className = 'fx-star';
    star.style.width = sSize + 'px';
    star.style.height = sSize + 'px';
    star.style.left = Math.random() * 100 + 'vw';
    star.style.top = Math.random() * 100 + 'vh';
    star.style.animationDuration = (Math.random() * 3 + 2) + 's';
    star.style.animationDelay = Math.random() * 2 + 's';
    document.body.appendChild(star);
  }
}

function cacheAppLogo() {
  var LOGO_URL = 'https://avatars.githubusercontent.com/u/168665654?v=4&size=64';
  document.querySelectorAll('.app-logo-icon img').forEach(function(img) {
    if (img.complete && img.naturalWidth > 0) {
      try {
        var canvas = document.createElement('canvas');
        canvas.width = img.naturalWidth || 64;
        canvas.height = img.naturalHeight || 64;
        var ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0);
        IC.set(LOGO_URL, canvas.toDataURL('image/png'));
      } catch(e) {}
    }
  });
  IC.load(LOGO_URL);
}

function boot() {
  createBubbles();
  updateCelestial();
  loadTheme();
  loadLayout();
  bind();
  loadUiPrefs();
  applyCredsModeUI();
  loadRadical();
  initTimeCard();
  refreshInfo();
  refreshSelected();
  loadSavedCredentials();
  try { updateOfflineCard(); } catch(e){}
  applyState(A.getStatus());
  startPolling();
  setInterval(function() { if (!app.busy) refreshInfo(); }, 30000);
  loadSettings();
  startFirebaseIntegration();
  setTimeout(cacheAppLogo, 2000);
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', boot);
} else {
  boot();
}

})();
</script>

